mapper.select:
/* projInqyDao1020 : 프로젝트 목록 조회 */ SELECT SUB_DATA.NUM , SUB_DATA.PROJ_ID , SUB_DATA.PROJ_TITLE , SUB_DATA.PROJ_CONT , SUB_DATA.STATUS_CD , C.CODE_NM AS STATUS_NM , SUB_DATA.PROJ_SDT , SUB_DATA.PROJ_EDT , SUB_DATA.ORG_NM , SUB_DATA.RANK_NM , SUB_DATA.OWNER_IDX , SUB_DATA.OWNER_NM , SUB_DATA.REG_DT , SUB_DATA.LIST_CNT FROM ( SELECT P.PROJ_ID , P.PROJ_TITLE , P.PROJ_CONT , TO_CHAR(P.PROJ_SDT, 'YYYYMMDD') AS PROJ_SDT , TO_CHAR(P.PROJ_EDT, 'YYYYMMDD') AS PROJ_EDT , P.STATUS_CD , P.OWNER_IDX , E.EMP_NM AS OWNER_NM , O.ORG_NM , R.RANK_NM , TO_CHAR(P.REG_DT, 'YYYYMMDD') AS REG_DT , ROW_NUMBER() OVER(ORDER BY P.PROJ_ID DESC) AS NUM , COUNT(*) OVER() AS LIST_CNT FROM PROJECT P LEFT OUTER JOIN EMP_INFO E ON P.OWNER_IDX = E.EMP_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD AND O.USE_YN = 'Y' LEFT OUTER JOIN RANK R ON R.RANK_CD = E.RANK_CD AND R.USE_YN = 'Y' WHERE P.USE_YN = 'Y'
AND REGEXP_REPLACE(LOWER(P.PROJ_TITLE),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND P.PROJ_EDT >= TO_DATE(#{srchSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
AND P.PROJ_SDT < TO_DATE(#{srchEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1
AND REGEXP_REPLACE(LOWER(O.ORG_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{orgNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(R.RANK_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{rankNm, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND REGEXP_REPLACE(LOWER(E.EMP_NM),'[^0-9가-힣A-Za-z]','') LIKE '%'||REGEXP_REPLACE(LOWER(#{srchIdx, jdbcType=VARCHAR}),'[^0-9가-힣A-Za-z]','')||'%'
AND P.STATUS_CD = #{srchStatCd, jdbcType=VARCHAR}
) SUB_DATA LEFT OUTER JOIN CODE C ON C.CODE_CD = SUB_DATA.STATUS_CD WHERE 1=1
AND SUB_DATA.NUM BETWEEN #{sIdx, jdbcType=NUMERIC} AND #{eIdx, jdbcType=NUMERIC}
ORDER BY SUB_DATA.NUM ASC

mapper.delete:
