DELETE FROM PROJECT
WHERE PROJ_ID IN

		#{deleteIdx, jdbcType=VARCHAR}

mapper.update:
/* projProcDao1030 : 프로젝트 수정 처리 */
UPDATE PROJECT
	SET PROJ_TITLE = #{projTitle, jdbcType=VARCHAR}
		, PROJ_CONT = #{projCont, jdbcType=VARCHAR}
		, STATUS_CD = #{statusCd, jdbcType=VARCHAR}
		, PROJ_SDT = TO_DATE(#{projSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
		, PROJ_EDT = TO_DATE(#{projEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
		, OWNER_IDX = #{ownerIdx, jdbcType=VARCHAR}
		, MOD_IDX = #{modIdx, jdbcType=VARCHAR}
		, MOD_DT = SYSDATE
WHERE PROJ_ID = #{projId, jdbcType=VARCHAR}
